create temporary view raw_data_${grass_region_without_quote} AS
select
    platform
    ,is_ads
    ,feature_detail
    ,user_id
    ,scenario_tags
    ,local_date
    ,sum(net_order_cnt) as net_order_cnt
    ,sum(nmv) as nmv
from base_table_${grass_region_without_quote}
where
    feature_detail is not null
    and size(scenario_tags) > 0
group by 1, 2, 3, 4, 5, 6

union all
select
    platform
    ,is_ads
    ,source1_feature_detail as feature_detail
    ,user_id
    ,source1_scenario_tags as scenario_tags
    ,local_date
    ,sum(net_order_cnt) as net_order_cnt
    ,sum(nmv) as nmv
from base_table_${grass_region_without_quote}
where
    nvl(source1_feature_detail, '') != ''
    and source1_feature_detail != feature_detail
    and size(source1_scenario_tags) > 0
group by 1, 2, 3, 4, 5, 6

union all
select
    platform
    ,is_ads
    ,source2_feature_detail as feature_detail
    ,user_id
    ,source2_scenario_tags as scenario_tags
    ,local_date
    ,sum(net_order_cnt) as net_order_cnt
    ,sum(nmv) as nmv
from base_table_${grass_region_without_quote}
where
    nvl(source2_feature_detail, '') != ''
    and source2_feature_detail != source1_feature_detail
    and source2_feature_detail != feature_detail
    and size(source2_scenario_tags) > 0
group by 1, 2, 3, 4, 5, 6
;

