create temporary view dws_tag_${grass_region_without_quote} AS
select
    platform
    ,is_ads
    ,'__ALL__' as feature_detail
    ,t1.user_id
    ,array_union(array_union(coalesce(scenario_tags, array()), coalesce(source1_scenario_tags, array())), coalesce(source2_scenario_tags, array())) as union_scenario_tags
    ,'__ALL__' as target_type
    ,t1.local_date
    ,coalesce(abs_tier_180d, '0') as abs_tier_180d

    ,sum(net_order_cnt) as net_order_cnt
    ,sum(nmv) as nmv
from
    base_table_${grass_region_without_quote} as t1
left join
    dim_user_${grass_region_without_quote} as t2
on
    t1.user_id = t2.user_id
    and date(t1.local_date) = date_add(date(t2.local_date), 1)
group by 1, 2, 4, 5, 7, 8;

